-- 205: Original BrillaPrep WASSCE BrillaPrep transitional Leatherwork beta content blueprint questions, part 3.
-- Curriculum-aligned practice content; not official WAEC examination material.
PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS _migration_205_guard (valid INTEGER NOT NULL CHECK (valid = 1));
DELETE FROM _migration_205_guard;
INSERT INTO _migration_205_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_leatherwork_b004_009' AND NOT (q.topic_id IS 'topic_was_leatherwork_b004_2' AND q.subject_id IS 'subj_wassce_leatherwork' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Which sequence best represents vegetable tanning after a cured hide enters production?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Soak and clean it, lime and unhair it, flesh and delime it, then expose the prepared pelt progressively to vegetable-tannin liquors before conditioning and drying","B. Soak and flesh the hide, begin with the strongest tannin liquor, then lime and unhair it after tannage","C. Pickle the pelt, carry out one chrome-tanning bath, and add vegetable dye during surface finishing","D. Wet-salt the hide, dry it fully, apply vegetable dye to the grain, then condition it without tannin penetration"]' AND q.correct_answer IS 'A' AND q.explanation IS 'Vegetable tanning follows beamhouse cleaning and pelt preparation, then introduces plant tannins through controlled liquors, commonly progressing from milder to stronger concentration so penetration develops before drying and finishing. Therefore the correct answer is A: Soak and clean it, lime and unhair it, flesh and delime it, then expose the prepared pelt progressively to vegetable-tannin liquors before conditioning and drying.' AND q.difficulty IS 'hard' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_leatherwork_b004_2' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO3' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_leatherwork_b004_009' AND NOT (r.batch_id IS 'wassce-visual-arts-beta-004' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Leatherwork practice aligned to WAEC Ghana examiner evidence and Ghana curriculum sources; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_205_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_leatherwork_b004_010' AND NOT (q.topic_id IS 'topic_was_leatherwork_b004_2' AND q.subject_id IS 'subj_wassce_leatherwork' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Which statement best describes tawing in leather production?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. A prepared skin is treated mainly with alum salts, commonly with salt and lubricating materials, to produce pale supple leather","B. A prepared pelt is moved through vegetable-tannin liquors until tannins stabilise and colour the collagen","C. A pickled pelt is treated with basic chromium salts and then basified to fix the chrome","D. A finished leather surface is bleached to a pale colour and coated without treating the collagen"]' AND q.correct_answer IS 'A' AND q.explanation IS 'Tawing is traditionally based on aluminium salts with salt and lubricating or binding ingredients. It yields light-coloured flexible material whose treatment is generally more water-sensitive than vegetable or chrome tannage. Therefore the correct answer is A: A prepared skin is treated mainly with alum salts, commonly with salt and lubricating materials, to produce pale supple leather.' AND q.difficulty IS 'easy' AND q.points IS '3' AND q.marks IS '3' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_leatherwork_b004_2' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_leatherwork_b004_010' AND NOT (r.batch_id IS 'wassce-visual-arts-beta-004' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Leatherwork practice aligned to WAEC Ghana examiner evidence and Ghana curriculum sources; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_205_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_leatherwork_b004_011' AND NOT (q.topic_id IS 'topic_was_leatherwork_b004_3' AND q.subject_id IS 'subj_wassce_leatherwork' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'How should a head knife be moved when making a controlled cut at the leather bench?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Sideways through the cut while the blade is twisted to correct direction","B. Away from the body and supporting hand along a clear cutting path","C. Toward the supporting hand while the fingers hold the pattern edge","D. Across leather balanced on the lap so the material can rotate freely"]' AND q.correct_answer IS 'B' AND q.explanation IS 'Securing the leather on a cutting board and directing the knife away from the body keeps hands outside the blade path and lets the sharpened edge follow the pattern predictably. Therefore the correct answer is B: Away from the body and supporting hand along a clear cutting path.' AND q.difficulty IS 'medium' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_leatherwork_b004_3' AND q.command_word IS 'Explain' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_leatherwork_b004_011' AND NOT (r.batch_id IS 'wassce-visual-arts-beta-004' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Leatherwork practice aligned to WAEC Ghana examiner evidence and Ghana curriculum sources; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_205_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_leatherwork_b004_012' AND NOT (q.topic_id IS 'topic_was_leatherwork_b004_3' AND q.subject_id IS 'subj_wassce_leatherwork' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'What is the primary use of a pricking iron in hand-stitched leatherwork?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Thin a fold line by shaving a taper from the flesh side","B. Crease a decorative line parallel to a finished edge","C. Mark or form evenly spaced stitch positions at a consistent angle","D. Open one round hole at a time for fitting press-stud hardware"]' AND q.correct_answer IS 'C' AND q.explanation IS 'A pricking iron establishes repeated spacing and orientation for a seam, guiding later awl work or stitching so the thread pattern remains regular. Therefore the correct answer is C: Mark or form evenly spaced stitch positions at a consistent angle.' AND q.difficulty IS 'hard' AND q.points IS '2' AND q.marks IS '2' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_leatherwork_b004_3' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO3' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_leatherwork_b004_012' AND NOT (r.batch_id IS 'wassce-visual-arts-beta-004' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Leatherwork practice aligned to WAEC Ghana examiner evidence and Ghana curriculum sources; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_was_leatherwork_b004_009', 'topic_was_leatherwork_b004_2', 'subj_wassce_leatherwork', 'exam_wassce', NULL, NULL, 'Which sequence best represents vegetable tanning after a cured hide enters production?', 'multiple_choice', NULL, '["A. Soak and clean it, lime and unhair it, flesh and delime it, then expose the prepared pelt progressively to vegetable-tannin liquors before conditioning and drying","B. Soak and flesh the hide, begin with the strongest tannin liquor, then lime and unhair it after tannage","C. Pickle the pelt, carry out one chrome-tanning bath, and add vegetable dye during surface finishing","D. Wet-salt the hide, dry it fully, apply vegetable dye to the grain, then condition it without tannin penetration"]', 'A', 'Vegetable tanning follows beamhouse cleaning and pelt preparation, then introduces plant tannins through controlled liquors, commonly progressing from milder to stronger concentration so penetration develops before drying and finishing. Therefore the correct answer is A: Soak and clean it, lime and unhair it, flesh and delime it, then expose the prepared pelt progressively to vegetable-tannin liquors before conditioning and drying.', 'hard', '1', '1', '90', NULL, NULL, '1', NULL, 'st_was_leatherwork_b004_2', 'Identify', 'AO3', NULL, NULL, 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_was_leatherwork_b004_010', 'topic_was_leatherwork_b004_2', 'subj_wassce_leatherwork', 'exam_wassce', NULL, NULL, 'Which statement best describes tawing in leather production?', 'multiple_choice', NULL, '["A. A prepared skin is treated mainly with alum salts, commonly with salt and lubricating materials, to produce pale supple leather","B. A prepared pelt is moved through vegetable-tannin liquors until tannins stabilise and colour the collagen","C. A pickled pelt is treated with basic chromium salts and then basified to fix the chrome","D. A finished leather surface is bleached to a pale colour and coated without treating the collagen"]', 'A', 'Tawing is traditionally based on aluminium salts with salt and lubricating or binding ingredients. It yields light-coloured flexible material whose treatment is generally more water-sensitive than vegetable or chrome tannage. Therefore the correct answer is A: A prepared skin is treated mainly with alum salts, commonly with salt and lubricating materials, to produce pale supple leather.', 'easy', '3', '3', '90', NULL, NULL, '1', NULL, 'st_was_leatherwork_b004_2', 'Identify', 'AO1', NULL, NULL, 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_was_leatherwork_b004_011', 'topic_was_leatherwork_b004_3', 'subj_wassce_leatherwork', 'exam_wassce', NULL, NULL, 'How should a head knife be moved when making a controlled cut at the leather bench?', 'multiple_choice', NULL, '["A. Sideways through the cut while the blade is twisted to correct direction","B. Away from the body and supporting hand along a clear cutting path","C. Toward the supporting hand while the fingers hold the pattern edge","D. Across leather balanced on the lap so the material can rotate freely"]', 'B', 'Securing the leather on a cutting board and directing the knife away from the body keeps hands outside the blade path and lets the sharpened edge follow the pattern predictably. Therefore the correct answer is B: Away from the body and supporting hand along a clear cutting path.', 'medium', '1', '1', '90', NULL, NULL, '1', NULL, 'st_was_leatherwork_b004_3', 'Explain', 'AO2', NULL, NULL, 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_was_leatherwork_b004_012', 'topic_was_leatherwork_b004_3', 'subj_wassce_leatherwork', 'exam_wassce', NULL, NULL, 'What is the primary use of a pricking iron in hand-stitched leatherwork?', 'multiple_choice', NULL, '["A. Thin a fold line by shaving a taper from the flesh side","B. Crease a decorative line parallel to a finished edge","C. Mark or form evenly spaced stitch positions at a consistent angle","D. Open one round hole at a time for fitting press-stud hardware"]', 'C', 'A pricking iron establishes repeated spacing and orientation for a seam, guiding later awl work or stitching so the thread pattern remains regular. Therefore the correct answer is C: Mark or form evenly spaced stitch positions at a consistent angle.', 'hard', '2', '2', '90', NULL, NULL, '1', NULL, 'st_was_leatherwork_b004_3', 'Identify', 'AO3', NULL, NULL, 'board_waec');
INSERT OR IGNORE INTO question_content_releases (question_id, batch_id, quality_assurance, release_channel, content_label, source_url, official_exam_board_content, feedback_enabled) SELECT id, 'wassce-visual-arts-beta-004', 'automated_beta', 'beta', 'Original BrillaPrep transitional Leatherwork practice aligned to WAEC Ghana examiner evidence and Ghana curriculum sources; not official WAEC examination material or a copied past paper.', 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf', 0, 1 FROM questions WHERE id IN ('q_was_leatherwork_b004_009', 'q_was_leatherwork_b004_010', 'q_was_leatherwork_b004_011', 'q_was_leatherwork_b004_012');
